निम्नलिखित C++ कोड स्निपेट का आउटपुट क्या होगा?
#include <iostream>
using namespace std;
int main() {
int a = 5;
cout << (a++ + ++a);
return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?
#include <iostream>
using namespace std;
int main() {
int x = 10, y = 20;
int &ref = x;
ref = y;
cout << x << " " << ref;
return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?
#include <iostream>
using namespace std;
void fun(int x = 10, int y = 20) {
cout << x + y;
}
int main() {
fun(5);
return 0;
}
